#include <coroutine>
#include <cstdint>

// 手写一个最简 Generator<T>
template <typename T>
struct Generator {
    struct promise_type {
        T current_value{};
        Generator get_return_object() {
            return Generator{std::coroutine_handle<promise_type>::from_promise(*this)};
        }
        std::suspend_always initial_suspend() noexcept { return {}; }
        std::suspend_always final_suspend() noexcept { return {}; }
        std::suspend_always yield_value(T value) { current_value = value; return {}; }
        void return_void() {}
        void unhandled_exception() { std::terminate(); }
    };

    std::coroutine_handle<promise_type> h_;
    explicit Generator(std::coroutine_handle<promise_type> h) : h_(h) {}
    ~Generator() { if (h_) h_.destroy(); }     // 别忘了销毁协程帧！

    bool next() { h_.resume(); return !h_.done(); }
    T value() const { return h_.promise().current_value; }
};

// 斐波那契无限序列
Generator<uint64_t> fibonacci() {
    uint64_t a = 0, b = 1;
    while (true) {
        co_yield a;
        auto t = a + b; a = b; b = t;
    }
}

#include <coroutine>

// 一个"立即完成"的最小 awaiter
struct Immediate {
    bool await_ready() noexcept { return true; }   // 不用挂起
    void await_suspend(std::coroutine_handle<>) noexcept {}
    int await_resume() noexcept { return 42; }     // 作为 co_await 的值
};

// 定时等待型 awaiter 的骨架
struct SleepFor {
    std::chrono::milliseconds dur;
    bool await_ready() noexcept { return dur.count() <= 0; }
    void await_suspend(std::coroutine_handle<> h) {
        timer_arm(dur, [h]{ h.resume(); });   // 到期后恢复协程
    }
    void await_resume() noexcept {}
};

