// 编译期生成素数表 —— vector 也能用了
consteval std::vector<int> primes_below(int limit) {
    std::vector<int> ps;
    for (int n = 2; n < limit; ++n) {
        bool prime = true;
        for (int d = 2; d * d <= n; ++d)
            if (n % d == 0) { prime = false; break; }
        if (prime) ps.push_back(n);
    }
    return ps;
}

