    // 取偶数 → 平方 → 前三个
    for (int x : nums | rv::filter([](int n){ return n % 2 == 0; })
                       | rv::transform([](int n){ return n * n; })
                       | rv::take(3)) {
        std::cout << x << " ";          // 64 16 36
    }

    // 无限序列 + 惰性截断：前 10 个偶数
