#include <semaphore>
#include <latch>
#include <barrier>
#include <thread>

std::counting_semaphore<4> slots(4);   // 最多 4 个并发
std::latch done(3);                     // 等 3 个任务完成
std::barrier sync(2, [] noexcept {     // 每轮结束打印
    /* completion function */
});

void task(int id) {
    slots.acquire();                    // P 操作
    // ... 受限并发的工作 ...
    slots.release();                    // V 操作
    done.count_down();                  // 报告完成
}

int main() {
    for (int i = 0; i < 10; ++i)
        std::jthread(task, i).detach();
    done.wait();                        // 全部完成后返回
}

#include <atomic>
