using namespace std::chrono_literals;

std::atomic<bool> ready{false};
std::atomic<int>  value{0};

void consumer() {
    // 阻塞等待 ready 变为 true（无需 mutex）
    ready.wait(false);
    std::printf("got %d\n", value.load());
}

void producer() {
    std::this_thread::sleep_for(100ms);
    value.store(42);
    ready.store(true);
    ready.notify_one();                 // 唤醒消费者
}

